# Hypothesis: Manhattan distance from seeds determines value
# Seeds: 0 at (11,8), 9 at (13,8)

def manhattan(r1, c1, r2, c2):
    return abs(r1 - r2) + abs(c1 - c2)

# Get positions at different distances from each seed
zeros_from_seed0 = []
nines_from_seed0 = []
zeros_from_seed9 = []
nines_from_seed9 = []

for r in range(25):
    for c in range(25):
        if d1_out[r][c] in [0, 9]:
            if d1_out[r][c] == 0:
                d0 = manhattan(r, c, 11, 8)
                d9 = manhattan(r, c, 13, 8)
                zeros_from_seed0.append((r, c, d0, d9))
                zeros_from_seed9.append((r, c, d0, d9))
            else:
                d0 = manhattan(r, c, 11, 8)
                d9 = manhattan(r, c, 13, 8)
                nines_from_seed0.append((r, c, d0, d9))
                nines_from_seed9.append((r, c, d0, d9))

print("First 20 positions with 0 in output:")
for pos in sorted(zeros_from_seed0)[:20]:
    print(f"  {pos}: dist0={pos[2]}, dist9={pos[3]}")

print("\nFirst 20 positions with 9 in output:")
for pos in sorted(nines_from_seed9)[:20]:
    print(f"  {pos}: dist0={pos[2]}, dist9={pos[3]}")

# Check: maybe it's about "closest to 0 wins" vs "closest to 9 wins"
print("\n\nChecking min distance rule:")

# For each position with 0 or 9, is the closer seed the same as output value?
correct = 0
incorrect = 0

for r, c, d0, d9 in zeros_from_seed0:
    if d0 <= d9:  # closer to or equally distant from 0
        correct += 1
    else:
        incorrect += 1

for r, c, d0, d9 in nines_from_seed9:
    if d9 <= d0:  # closer to or equally distant from 9
        correct += 1
    else:
        incorrect += 1

print(f"Positions matching min-distance rule: {correct}/{len(zeros_from_seed0) + len(nines_from_seed9)}")
print(f"Positions NOT matching min-distance rule: {incorrect}")

# Count mismatches
pos_no_match = []
for r, c, d0, d9 in zeros_from_seed0:
    if d0 > d9:
        pos_no_match.append((r, c, d0, d9))

for r, c, d0, d9 in nines_from_seed9:
    if d9 > d0:
        pos_no_match.append((r, c, d0, d9))

print(f"\nPositions that violate min-distance rule:")
for r, c, d0, d9 in sorted(pos_no_match)[:20]:
    print(f"  ({r},{c}): output value, dist0={d0}, dist9={d9}")

